    attempt_id: str
    trajectory_id: str
    task_digest: str
    policy_version: str
    harness_digest: str
    reward_digest: str
    sampling_digest: str

    def __post_init__(self):
        if any(not isinstance(v, str) or not v.strip() for v in asdict(self).values()):
            raise ValueError("identity fields must be nonempty strings")

    def to_dict(self):
        return asdict(self)

    @property
    def group_key(self):
        value = self.to_dict()
        for key in ("slot_id", "attempt_id", "trajectory_id"):
            value.pop(key)
        return digest(value)
